-- ── story 1-2b: the client receiving policy ──────────────────────────────
-- Generated by drizzle-kit (the four `clients` policy columns,
-- `goods_receipt_lines.tolerance_qty`, the three `qc_holds` columns, the
-- grn-line index and the narrowed open-scope index) and hand-amended below
-- the marker: the CHECKs, the notifications source vocabulary widened with
-- `qc-receipt`, and the post-migration probes (drizzle-kit is blind to all
-- of them; `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive: every new column carries a default that reproduces the pre-1-2b
-- behaviour exactly (tolerance 0, no QC on receipt, no expiry rule, a
-- `manual` hold). No data is rewritten. No foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- The open-scope index is DROPPED and re-created with `AND kind = 'manual'`
-- in its predicate: a receipt hold is line-scoped and never takes part in
-- the one-open-hold-per-(sku, bin) rule. Every existing row is `manual`
-- (the column default), so the re-created index admits exactly the rows the
-- old one did — no row can violate it.
--
-- Lock cost: the CHECKs scan `clients` (tens of rows), `goods_receipt_lines`
-- and `qc_holds` once at deploy; the notifications CHECK re-add scans
-- `notifications` (as 0070 and 0071 did).
DROP INDEX "qc_holds_open_scope_unique";--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "receiving_tolerance_bps" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "qc_on_receipt" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "expiry_required" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "clients" ADD COLUMN "min_shelf_life_days" integer;--> statement-breakpoint
ALTER TABLE "goods_receipt_lines" ADD COLUMN "tolerance_qty" bigint DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "qc_holds" ADD COLUMN "kind" text DEFAULT 'manual' NOT NULL;--> statement-breakpoint
ALTER TABLE "qc_holds" ADD COLUMN "grn_line_id" uuid;--> statement-breakpoint
ALTER TABLE "qc_holds" ADD COLUMN "over_receipt_id" uuid;--> statement-breakpoint
CREATE INDEX "qc_holds_tenant_grn_line_idx" ON "qc_holds" USING btree ("tenant_id","grn_line_id");--> statement-breakpoint
CREATE UNIQUE INDEX "qc_holds_open_scope_unique" ON "qc_holds" USING btree ("tenant_id","warehouse_id","sku_id","bin_id") WHERE status = 'open' AND kind = 'manual';
--> statement-breakpoint
-- ── hand-amended: the receiving policy CHECKs (migration SQL only) ────────
-- Mirrored by `ClientsCommand.updateReceivingPolicy`, which answers a named
-- 400 first. `min_shelf_life_days` is nullable, so each arm says IS NULL
-- first (IMPLEMENTATION-GUIDE §3).
ALTER TABLE "clients" ADD CONSTRAINT "clients_receiving_tolerance_range" CHECK (
	"receiving_tolerance_bps" BETWEEN 0 AND 10000
);--> statement-breakpoint
ALTER TABLE "clients" ADD CONSTRAINT "clients_min_shelf_life_range" CHECK (
	"min_shelf_life_days" IS NULL OR "min_shelf_life_days" BETWEEN 1 AND 3650
);--> statement-breakpoint
-- A minimum remaining life means nothing unless an expiry is required.
ALTER TABLE "clients" ADD CONSTRAINT "clients_min_shelf_life_needs_expiry" CHECK (
	"min_shelf_life_days" IS NULL OR "expiry_required"
);--> statement-breakpoint
-- ── hand-amended: the within-tolerance slice of a GRN line ────────────────
ALTER TABLE "goods_receipt_lines" ADD CONSTRAINT "goods_receipt_lines_tolerance_qty_range" CHECK (
	"tolerance_qty" >= 0 AND "tolerance_qty" <= "applied_qty"
);--> statement-breakpoint
-- ── hand-amended: the hold kinds ──────────────────────────────────────────
-- A receipt hold always names its GRN line, a manual one never does; an
-- over-receipt id rides only on a receipt hold. Pinned against
-- `QC_HOLD_KINDS` (modules/inbound/qc.command.ts) by
-- test/client-receiving-policy.spec.ts.
ALTER TABLE "qc_holds" ADD CONSTRAINT "qc_holds_kind_check" CHECK (
	"kind" IN ('manual', 'receipt')
);--> statement-breakpoint
ALTER TABLE "qc_holds" ADD CONSTRAINT "qc_holds_kind_pairing" CHECK (
	("kind" = 'receipt') = ("grn_line_id" IS NOT NULL)
	AND ("over_receipt_id" IS NULL OR "kind" = 'receipt')
);--> statement-breakpoint
-- ── hand-amended: the notifications source vocabulary, widened ───────────
-- Drop and re-add (the 0070/0071 precedent): `qc-receipt` — ONE entry per
-- receipt (or approved excess) placed on QC holds. Pinned against
-- `NOTIFICATION_SOURCE_TYPES` by test/notifications.spec.ts.
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_source_type_check";--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_source_type_check" CHECK ("source_type" IN (
	'stock-adjustment', 'count-variance', 'over-receipt', 'rejected-op',
	'reorder-breach', 'batch-alert', 'qc-hold', 'channel-sync', 'audit-export',
	'ledger-chain-break', 'qc-receipt'
));--> statement-breakpoint
-- ── hand-amended: the hold reference index (the 0069 shape) ──────────────
-- Every reader of a hold's own `qc.held` events (putaway's open receipt-hold
-- quantity, the awaiting-putaway tile, the holds list's held quantity)
-- matches `reference_doc->>'holdId'`; each carries `reference_doc ? 'holdId'`
-- beside the equality so the planner can prove this partial index applies
-- (IMPLEMENTATION-GUIDE §9). SQL-only, like 0069's ledger reference indexes
-- (drizzle-kit does not model an expression index here). DEPLOY NOTE (0069's):
-- one transaction, so not CONCURRENTLY — against a large live ledger, pre-build
-- it CONCURRENTLY by hand under this exact name (IF NOT EXISTS then skips it).
CREATE INDEX IF NOT EXISTS "ledger_events_hold_ref_idx" ON "ledger_events" USING btree ("tenant_id","warehouse_id",("reference_doc"->>'holdId')) WHERE "reference_doc" ? 'holdId';--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0077 model) ────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	b uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: a client at the defaults, one at the policy
	-- ceilings; a GRN line with tolerance within its applied slice; an open
	-- MANUAL hold and two open RECEIPT holds on the same (sku, bin) scope (the
	-- narrowed index admits them), one naming an over-receipt; a
	-- `qc-receipt` notification.
	BEGIN
		INSERT INTO "clients" ("id","tenant_id","code","name","status","system_owned")
		VALUES (gen_random_uuid(), t, 'P-0078-A', 'probe a', 'active', false);
		INSERT INTO "clients" ("id","tenant_id","code","name","status","system_owned",
		                       "receiving_tolerance_bps","qc_on_receipt","expiry_required","min_shelf_life_days")
		VALUES (gen_random_uuid(), t, 'P-0078-B', 'probe b', 'active', false, 10000, true, true, 3650);
		INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","tolerance_qty")
		VALUES (gen_random_uuid(), t, gen_random_uuid(), s, 105000, 105000, 5000);
		INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at")
		VALUES (gen_random_uuid(), t, w, s, b, 'manual probe', 'open', u, now());
		INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","kind","grn_line_id")
		VALUES (gen_random_uuid(), t, w, s, b, 'receipt probe 1', 'open', u, now(), 'receipt', gen_random_uuid()),
		       (gen_random_uuid(), t, w, s, b, 'receipt probe 2', 'open', u, now(), 'receipt', gen_random_uuid());
		INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at","kind","grn_line_id","over_receipt_id")
		VALUES (gen_random_uuid(), t, w, s, b, 'excess probe', 'open', u, now(), 'receipt', gen_random_uuid(), gen_random_uuid());
		INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","warehouse_id","summary","raised_at","surfaced_at")
		VALUES (gen_random_uuid(), t, 'qc-receipt', gen_random_uuid(), w, '{"grnCode":"GRN-0001"}'::jsonb, now(), now());
		RAISE EXCEPTION USING ERRCODE = 'P0078', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0078: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0078' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'tolerance negative', 'tolerance over 100%', 'min life zero', 'min life over ten years',
		'min life without expiry', 'tolerance past applied', 'tolerance negative qty',
		'unknown kind', 'receipt hold without a line', 'manual hold with a line',
		'manual hold with an over-receipt', 'second open manual hold', 'unknown source type'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'tolerance negative' THEN 'clients_receiving_tolerance_range'
			WHEN 'tolerance over 100%' THEN 'clients_receiving_tolerance_range'
			WHEN 'min life zero' THEN 'clients_min_shelf_life_range'
			WHEN 'min life over ten years' THEN 'clients_min_shelf_life_range'
			WHEN 'min life without expiry' THEN 'clients_min_shelf_life_needs_expiry'
			WHEN 'tolerance past applied' THEN 'goods_receipt_lines_tolerance_qty_range'
			WHEN 'tolerance negative qty' THEN 'goods_receipt_lines_tolerance_qty_range'
			WHEN 'unknown kind' THEN 'qc_holds_kind_check'
			WHEN 'receipt hold without a line' THEN 'qc_holds_kind_pairing'
			WHEN 'manual hold with a line' THEN 'qc_holds_kind_pairing'
			WHEN 'manual hold with an over-receipt' THEN 'qc_holds_kind_pairing'
			WHEN 'second open manual hold' THEN 'qc_holds_open_scope_unique'
			ELSE 'notifications_source_type_check'
		END;
		BEGIN
			CASE probe
				WHEN 'tolerance negative' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","receiving_tolerance_bps") VALUES (gen_random_uuid(), t, 'P-0078-C', 'p', -1);
				WHEN 'tolerance over 100%' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","receiving_tolerance_bps") VALUES (gen_random_uuid(), t, 'P-0078-C', 'p', 10001);
				WHEN 'min life zero' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","expiry_required","min_shelf_life_days") VALUES (gen_random_uuid(), t, 'P-0078-C', 'p', true, 0);
				WHEN 'min life over ten years' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","expiry_required","min_shelf_life_days") VALUES (gen_random_uuid(), t, 'P-0078-C', 'p', true, 3651);
				WHEN 'min life without expiry' THEN
					INSERT INTO "clients" ("id","tenant_id","code","name","expiry_required","min_shelf_life_days") VALUES (gen_random_uuid(), t, 'P-0078-C', 'p', false, 30);
				WHEN 'tolerance past applied' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","tolerance_qty")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), s, 105000, 100000, 100001);
				WHEN 'tolerance negative qty' THEN
					INSERT INTO "goods_receipt_lines" ("id","tenant_id","grn_id","sku_id","qty","applied_qty","tolerance_qty")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), s, 105000, 100000, -1);
				WHEN 'unknown kind' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","held_by","held_at","kind","grn_line_id")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', u, now(), 'auto', gen_random_uuid());
				WHEN 'receipt hold without a line' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","held_by","held_at","kind")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', u, now(), 'receipt');
				WHEN 'manual hold with a line' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","held_by","held_at","grn_line_id")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', u, now(), gen_random_uuid());
				WHEN 'manual hold with an over-receipt' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","held_by","held_at","over_receipt_id")
					VALUES (gen_random_uuid(), t, w, s, b, 'p', u, now(), gen_random_uuid());
				WHEN 'second open manual hold' THEN
					INSERT INTO "qc_holds" ("id","tenant_id","warehouse_id","sku_id","bin_id","reason","status","held_by","held_at")
					VALUES (gen_random_uuid(), t, w, s, b, 'p1', 'open', u, now()), (gen_random_uuid(), t, w, s, b, 'p2', 'open', u, now());
				WHEN 'unknown source type' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'qc-receipts', gen_random_uuid(), '{}'::jsonb, now(), now());
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0078: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "clients" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "goods_receipt_lines" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "qc_holds" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "notifications" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0078: a probe row survived.';
	END IF;
END $$;
